/* HomeGlo — Interactive Shop the Look */
.hg-hotspot-look{
  padding:96px 0 104px;
  background:#f6f0e8;
  color:#2b2622;
  overflow:hidden;
}
.hg-hotspot-look-head{
  display:grid;
  grid-template-columns:minmax(0,1.1fr) minmax(300px,.65fr);
  gap:54px;
  align-items:end;
  margin-bottom:30px;
}
.hg-hotspot-look-kicker{
  margin:0 0 9px!important;
  color:#5c6b4f!important;
  font:700 9px/1.3 "Manrope",sans-serif!important;
  letter-spacing:.17em;
  text-transform:uppercase;
}
.hg-hotspot-look h2{
  margin:0!important;
  color:#2b2622!important;
  font:500 clamp(48px,6vw,78px)/.9 "Cormorant Garamond",serif!important;
  letter-spacing:-.045em;
}
.hg-hotspot-look-head-copy p{
  margin:0 0 14px!important;
  color:#746d64!important;
  font:400 11px/1.75 "Manrope",sans-serif!important;
}
.hg-hotspot-look-head-copy>a{
  display:inline-flex;
  gap:8px;
  align-items:center;
  color:#2b2622!important;
  text-decoration:none!important;
  border-bottom:1px solid currentColor;
  padding-bottom:3px;
  font:700 8.5px/1.3 "Manrope",sans-serif!important;
  letter-spacing:.06em;
  text-transform:uppercase;
}

.hg-hotspot-look-frame{position:relative}
.hg-hotspot-look-scene{
  position:relative;
  min-height:720px;
  background:#cfc5b9;
  overflow:hidden;
}
.hg-hotspot-look-scene>img{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center 48%;
}
.hg-hotspot-look-vignette{
  position:absolute;
  inset:0;
  z-index:1;
  background:linear-gradient(90deg,rgba(24,20,17,.24) 0%,rgba(24,20,17,.04) 42%,rgba(24,20,17,0) 72%);
  pointer-events:none;
}
.hg-hotspot-look-pin{
  position:absolute!important;
  z-index:5;
  left:var(--hg-pin-x)!important;
  top:var(--hg-pin-y)!important;
  width:36px!important;
  height:36px!important;
  margin:0!important;
  padding:0!important;
  border:0!important;
  border-radius:50%!important;
  background:#fff!important;
  color:#2b2622!important;
  box-shadow:0 8px 24px rgba(31,26,22,.2)!important;
  transform:translate(-50%,-50%)!important;
  cursor:pointer!important;
}
.hg-hotspot-look-dot{
  position:absolute;
  inset:0;
  display:grid;
  place-items:center;
  z-index:2;
  border-radius:50%;
  font:500 18px/1 "Manrope",sans-serif;
  transition:transform .22s ease,background .22s ease,color .22s ease;
}
.hg-hotspot-look-pulse{
  position:absolute;
  inset:-8px;
  border:1px solid rgba(255,255,255,.7);
  border-radius:50%;
  animation:hgLookPulse 2.2s ease-out infinite;
}
.hg-hotspot-look-pin.is-active .hg-hotspot-look-dot{background:#c4693b;color:#fff;transform:rotate(45deg)}
.hg-hotspot-look-pin.is-active .hg-hotspot-look-pulse{border-color:rgba(196,105,59,.55)}
.hg-hotspot-look-pin-label{
  position:absolute;
  left:46px;
  top:50%;
  transform:translateY(-50%);
  min-width:max-content;
  padding:7px 9px;
  border-radius:5px;
  background:rgba(34,29,25,.78);
  color:#fff;
  backdrop-filter:blur(8px);
  font:700 7.5px/1 "Manrope",sans-serif;
  letter-spacing:.04em;
  text-transform:uppercase;
  opacity:0;
  pointer-events:none;
  transition:opacity .18s ease,transform .18s ease;
}
.hg-hotspot-look-pin:hover .hg-hotspot-look-pin-label,
.hg-hotspot-look-pin:focus-visible .hg-hotspot-look-pin-label,
.hg-hotspot-look-pin.is-active .hg-hotspot-look-pin-label{
  opacity:1;
  transform:translate(2px,-50%);
}
@keyframes hgLookPulse{
  0%{transform:scale(.72);opacity:.8}
  70%,100%{transform:scale(1.28);opacity:0}
}

.hg-hotspot-look-card-stack{
  position:absolute;
  z-index:6;
  left:26px;
  bottom:26px;
  width:min(390px,calc(100% - 52px));
}
.hg-hotspot-look-card{
  display:grid;
  grid-template-columns:116px minmax(0,1fr);
  min-height:142px;
  border:1px solid rgba(255,255,255,.58);
  border-radius:11px;
  background:rgba(255,251,246,.95);
  box-shadow:0 20px 60px rgba(29,24,20,.18);
  backdrop-filter:blur(16px);
  overflow:hidden;
}
.hg-hotspot-look-card[hidden]{display:none!important}
.hg-hotspot-look-card.is-active{animation:hgLookCardIn .25s ease both}
@keyframes hgLookCardIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
.hg-hotspot-look-card-media{display:block;min-height:142px;background:#e9e1d8;overflow:hidden}
.hg-hotspot-look-card-media img{display:block;width:100%;height:100%;object-fit:cover}
.hg-hotspot-look-card-copy{display:flex;min-width:0;flex-direction:column;padding:14px}
.hg-hotspot-look-card-copy>p{
  margin:0!important;
  color:#5c6b4f!important;
  font:700 7px/1.3 "Manrope",sans-serif!important;
  letter-spacing:.1em;
  text-transform:uppercase;
}
.hg-hotspot-look-card h3{
  margin:5px 0 4px!important;
  color:#2b2622!important;
  font:600 20px/1.03 "Cormorant Garamond",serif!important;
}
.hg-hotspot-look-card h3 a{color:inherit!important;text-decoration:none!important}
.hg-hotspot-look-category{color:#8a8378;font:500 7.5px/1.4 "Manrope",sans-serif}
.hg-hotspot-look-category a{color:inherit!important;text-decoration:none!important}
.hg-hotspot-look-card-bottom{
  display:flex;
  align-items:end;
  justify-content:space-between;
  gap:12px;
  margin-top:auto;
  padding-top:10px;
}
.hg-hotspot-look-price{color:#2b2622;font:700 9px/1.2 "Manrope",sans-serif}
.hg-hotspot-look-price del{opacity:.5;margin-right:3px}
.hg-hotspot-look-price ins{background:transparent;text-decoration:none}
.hg-hotspot-look-actions{display:flex;align-items:center;gap:6px}
.hg-hotspot-look-view{
  color:#746d64!important;
  font:700 7px/1 "Manrope",sans-serif!important;
  text-transform:uppercase;
  text-decoration:underline!important;
  text-underline-offset:3px;
}
.hg-hotspot-look-cart{
  display:flex!important;
  align-items:center;
  justify-content:center;
  gap:4px;
  min-height:31px!important;
  padding:0 9px!important;
  border:1px solid #2b2622!important;
  border-radius:5px!important;
  background:#2b2622!important;
  color:#fff!important;
  text-decoration:none!important;
  font:700 7px/1 "Manrope",sans-serif!important;
  text-transform:uppercase;
}
.hg-hotspot-look-cart svg{width:11px;height:11px;fill:none;stroke:currentColor;stroke-width:1.6}

.hg-hotspot-look-guide{
  position:absolute;
  z-index:3;
  right:21px;
  bottom:19px;
  display:flex;
  align-items:center;
  gap:7px;
  padding:7px 9px;
  border-radius:999px;
  background:rgba(28,24,21,.62);
  color:#fff;
  backdrop-filter:blur(8px);
  font:600 7.5px/1 "Manrope",sans-serif;
  letter-spacing:.04em;
  text-transform:uppercase;
}
.hg-hotspot-look-guide span{width:6px;height:6px;border-radius:50%;background:#c4693b}

.hg-hotspot-look-mobile-tabs{display:none}
.hg-hotspot-look-note{
  margin:12px 0 0!important;
  color:#8a8378!important;
  font:400 8px/1.5 "Manrope",sans-serif!important;
  text-align:right;
}

@media(max-width:900px){
  .hg-hotspot-look{padding:72px 0 78px}
  .hg-hotspot-look-head{grid-template-columns:1fr;gap:16px}
  .hg-hotspot-look-scene{min-height:620px}
}
@media(max-width:680px){
  .hg-hotspot-look{padding:52px 0 58px}
  .hg-hotspot-look .hg-shell{width:calc(100% - 24px)!important}
  .hg-hotspot-look h2{font-size:50px!important}
  .hg-hotspot-look-scene{min-height:500px;border-radius:10px}
  .hg-hotspot-look-scene>img{object-position:center center}
  .hg-hotspot-look-vignette{background:linear-gradient(0deg,rgba(24,20,17,.28),rgba(24,20,17,0) 52%)}
  .hg-hotspot-look-pin{width:34px!important;height:34px!important}
  .hg-hotspot-look-pin-label{display:none}
  .hg-hotspot-look-card-stack{
    position:relative;
    left:auto;
    bottom:auto;
    width:100%;
    margin-top:10px;
  }
  .hg-hotspot-look-card{
    grid-template-columns:92px minmax(0,1fr);
    min-height:116px;
    box-shadow:none;
    border-color:#dfd6cb;
    background:#fff;
  }
  .hg-hotspot-look-card-media{min-height:116px}
  .hg-hotspot-look-card h3{font-size:18px!important}
  .hg-hotspot-look-guide{right:10px;bottom:10px}
  .hg-hotspot-look-mobile-tabs{
    display:flex;
    gap:6px;
    overflow-x:auto;
    margin-top:10px;
    padding:0 0 4px;
    scrollbar-width:none;
  }
  .hg-hotspot-look-mobile-tabs::-webkit-scrollbar{display:none}
  .hg-hotspot-look-mobile-tabs button{
    flex:none;
    display:flex;
    align-items:center;
    gap:7px;
    min-height:36px;
    padding:0 10px;
    border:1px solid #d8d0c5;
    border-radius:999px;
    background:#fff;
    color:#746d64;
    font:700 7.5px/1 "Manrope",sans-serif;
    text-transform:uppercase;
    cursor:pointer;
  }
  .hg-hotspot-look-mobile-tabs button span{color:#c4693b}
  .hg-hotspot-look-mobile-tabs button.is-active{border-color:#2b2622;background:#2b2622;color:#fff}
  .hg-hotspot-look-note{text-align:left}
}
@media(prefers-reduced-motion:reduce){
  .hg-hotspot-look-pulse{animation:none}
  .hg-hotspot-look-card.is-active{animation:none}
  .hg-hotspot-look-pin-label,.hg-hotspot-look-dot{transition:none}
}
